#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int swaps = 0;
    for (int i = 0; i < n - 1; i++) {
        int min_index = i;
        for (int j = i + 1; j < n; j++) {
            if (values[j] < values[min_index]) {
                min_index = j;
            }
        }
        if (min_index != i) {
            int tmp = values[i];
            values[i] = values[min_index];
            values[min_index] = tmp;
            swaps++;
        }
    }
    printf("%d\n", swaps);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", values[i]);
    }
    return 0;
}

