#include <stdio.h>

static int values[100000];
static bool visited[100000];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int cycles = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i]) {
            continue;
        }
        cycles++;
        for (int j = i; !visited[j]; j = values[j] - 1) {
            visited[j] = true;
        }
    }
    printf("%d\n", n - cycles);
    return 0;
}

