    int v[] = {3, 1, 2};
    int n = 3, swaps = 0;
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) {
            if (v[j] < v[m]) {
                m = j;
            }
        }
        if (m != i) {
            int t = v[i];
            v[i] = v[m];
            v[m] = t;
            swaps++;
        }
    }
    printf("%d %d %d %d\n", v[0], v[1], v[2], swaps);
    return 0;
}
